# ---- Log-concavity check ----------------------------------------------------
# Verifies that the sequence of slopes is non-increasing (required for a
# log-concave density). Throws an error if violated.
check_log_concave <- function(xs, hs, hps, logh) {
  ok <- TRUE
  for (i in seq_len(length(xs) - 1L)) {
    if (hps[i] < hps[i + 1L]) ok <- FALSE
  }
  if (!ok) {
    stop("Target is not log-concave: slopes of the log-density are not ",
         "monotonically non-increasing. ARS requires a log-concave target.",
         call. = FALSE)
  }
  TRUE
}

# ---- Initial abscissae ------------------------------------------------------
# Find at least two starting points whose slopes bracket zero (one positive,
# one negative), plus the domain endpoints if finite.
find_initial_points <- function(logh, domain) {
  lo <- domain[1]; hi <- domain[2]
  mid <- (lo + hi) / 2
  x0 <- mid
  hp0 <- h_prime(x0, logh)
  x1 <- x0 - 1; x2 <- x0 + 1
  if (x1 < lo) x1 <- lo + 0.1 * (hi - lo)
  if (x2 > hi) x2 <- hi - 0.1 * (hi - lo)
  hp1 <- h_prime(x1, logh); hp2 <- h_prime(x2, logh)
  xs <- c(x0, x1, x2)
  hps <- c(hp0, hp1, hp2)
  for (it in 1:50) {
    pos <- which(hps > 0)
    neg <- which(hps < 0)
    if (length(pos) >= 1 && length(neg) >= 1) break
    if (length(pos) < 1) {
      x_new <- x0 - (x0 - lo) * 0.5
      if (x_new < lo) break
    } else {
      x_new <- x0 + (hi - x0) * 0.5
      if (x_new > hi) break
    }
    xs <- c(xs, x_new)
    hps <- c(hps, h_prime(x_new, logh))
  }
  xs <- sort(unique(xs))
  xs <- xs[is.finite(xs) & xs >= lo & xs <= hi]
  if (is.finite(lo)) xs <- c(lo, xs)
  if (is.finite(hi)) xs <- c(xs, hi)
  xs <- sort(unique(xs))
  if (length(xs) < 2) stop("Could not find at least two valid initial points.", call. = FALSE)
  list(xs = xs, hps = h_prime(xs, logh), hs = logh(xs))
}

# ---- Upper hull -------------------------------------------------------------
# Builds the piecewise-linear upper hull u(x) through points (x_i, h_i) with
# slopes h'_i. Returns list with xs, hs, hps, breakpoints (alpha_i).
build_upper_hull <- function(xs, hs, hps) {
  n <- length(xs)
  if (n == 2L) {
    alpha <- (hs[2] - hs[1] - hps[2] * xs[2] + hps[1] * xs[1]) / (hps[1] - hps[2])
    alpha <- min(max(alpha, xs[1]), xs[2])
    return(list(xs = xs, hs = hs, hps = hps, alpha = c(-Inf, alpha, Inf)))
  }
  alpha <- numeric(n + 1L)
  alpha[1] <- -Inf; alpha[n + 1L] <- Inf
  for (i in seq_len(n - 1L)) {
    if (hps[i] == hps[i + 1L]) {
      alpha[i + 1L] <- (xs[i] + xs[i + 1L]) / 2
    } else {
      a <- (hs[i + 1L] - hs[i] - hps[i + 1L] * xs[i + 1L] + hps[i] * xs[i]) / (hps[i] - hps[i + 1L])
      alpha[i + 1L] <- min(max(a, xs[i]), xs[i + 1L])
    }
  }
  list(xs = xs, hs = hs, hps = hps, alpha = alpha)
}
