# ---- Upper hull value u(x) --------------------------------------------------
upper_hull_val <- function(x, hull) {
  i <- findInterval(x, hull$alpha, rightmost.closed = TRUE)
  i <- min(max(i, 1L), length(hull$xs))
  hull$hs[i] + hull$hps[i] * (x - hull$xs[i])
}

# ---- Lower hull (squeeze) value l(x) ----------------------------------------
lower_hull_val <- function(x, xs, hs) {
  n <- length(xs)
  if (x < xs[1L] || x > xs[n]) return(-Inf)
  i <- findInterval(x, xs, rightmost.closed = TRUE)
  i <- min(max(i, 1L), n - 1L)
  hs[i] + (hs[i + 1L] - hs[i]) / (xs[i + 1L] - xs[i]) * (x - xs[i])
}

# ---- Areas (mass) under each segment of the upper hull ----------------------
# A_i = integral of exp(u(x)) over [alpha_i, alpha_{i+1}); integrable because
# the leftmost slope is > 0 and the rightmost slope is < 0 on unbounded ends.
hull_areas <- function(hull) {
  n <- length(hull$xs)
  A <- numeric(n)
  for (i in seq_len(n)) {
    m <- hull$hps[i]; c <- hull$hs[i] - m * hull$xs[i]
    aL <- hull$alpha[i]; aR <- hull$alpha[i + 1L]
    if (abs(m) < 1e-12) {
      if (!is.finite(aL) || !is.finite(aR))
        stop("Upper hull segment has zero slope on an infinite interval.", call. = FALSE)
      A[i] <- exp(c) * (aR - aL)
    } else {
      eL <- exp(m * aL); eR <- exp(m * aR)
      A[i] <- exp(c) * (eR - eL) / m
    }
    if (!is.finite(A[i]) || A[i] < 0)
      stop("Non-finite area in upper hull: slopes may not bracket the mode.", call. = FALSE)
  }
  A
}

# ---- Draw one candidate x* from the upper hull ------------------------------
sample_upper_hull <- function(hull, A, total) {
  n <- length(hull$xs)
  idx <- findInterval(runif(1) * total, cumsum(A)) + 1L
  idx <- min(max(idx, 1L), n)
  m <- hull$hps[idx]; c <- hull$hs[idx] - m * hull$xs[idx]
  aL <- hull$alpha[idx]; aR <- hull$alpha[idx + 1L]
  u <- runif(1)
  if (abs(m) < 1e-12) {
    x <- aL + u * (aR - aL)
  } else {
    eL <- exp(m * aL); eR <- exp(m * aR)
    x <- log(eL + u * (eR - eL)) / m
  }
  list(x = x, uval = hull$hs[idx] + m * (x - hull$xs[idx]))
}
