content = r'''# =============================================================================
# Adaptive Rejection Sampling (Gilks & Wild, 1992)
# A modular implementation in R.
#   - validate_ars_inputs : checks the user-supplied arguments
#   - make_logh           : converts a (unnormalised) density to its log
#   - h_prime             : numeric first derivative of the log-density
#   - check_log_concave   : verifies the target is log-concave
#   - find_initial_points : picks starting abscissae that bracket the mode
#   - build_upper_hull    : constructs the piecewise-linear upper hull
#   - hull_areas          : areas under each upper-hull segment
#   - sample_upper_hull   : draws one candidate from the upper-hull proposal
#   - upper/lower_hull_val: evaluate the squeeze (lower) hull
#   - ars                 : the top-level sampler
#   - test                : formal self-tests against known distributions
# =============================================================================

# ---- Input validation -------------------------------------------------------
validate_ars_inputs <- function(density_function, domain, n) {
  if (!is.function(density_function))
    stop("density_function must be a function", call. = FALSE)
  if (missing(n)) n <- 1000L
  if (!is.numeric(n) || length(n) != 1L || is.na(n) || n < 1 || n != floor(n))
    stop("n must be a positive integer", call. = FALSE)
  if (!is.numeric(domain) || length(domain) != 2L || any(is.na(domain)))
    stop("domain must be a numeric vector of length 2 (lower, upper)", call. = FALSE)
  if (!is.finite(domain) || domain[1] >= domain[2])
    stop("domain must be c(lower, upper) with lower < upper", call. = FALSE)
  list(n = as.integer(n), domain = as.numeric(domain))
}

# ---- Log-density wrapper ----------------------------------------------------
# Turns an (unnormalised) density into its log; non-positive / NA -> -Inf.
make_logh <- function(density_function) {
  function(x) {
    d <- as.numeric(density_function(x))
    d[is.na(d) | d <= 0] <- 0
    log(pmax(d, 0))
  }
}

# ---- Numeric first derivative of the log-density (vectorised) ---------------
h_prime <- function(x, logh) {
  eps <- 1e-6
  sapply(x, function(xi) {
    fx <- logh(xi)
    fp <- logh(xi + eps)
    fm <- logh(xi - eps)
    d <- (fp - fm) / (2 * eps)
    if (!is.finite(d)) {
      if (is.finite(fp)) d <- (fp - fx) / eps
      else if (is.finite(fm)) d <- (fx - fm) / eps
      else d <- 0
    }
    d
  })
}

# ---- Log-concavity check ----------------------------------------------------
# For a log-concave target the derivative of the log-density is non-increasing
# (within a small tolerance to absorb numeric-derivative noise).
check_log_concave <- function(xs, hps, tol = 1e-5) {
  if (length(xs) < 2L) return(TRUE)
  if (any(diff(hps) > tol)) {
    stop("Target is not log-concave: the derivative of the log-density is not ",
         "monotonically non-increasing. ARS requires a log-concave target.",
         call. = FALSE)
  }
  TRUE
}

# ---- Initial abscissae ------------------------------------------------------
# Pick a small set of starting points. For an open (-Inf) end we need a point
# with positive slope (so the left tail integrates); for an open (+Inf) end we
# need a point with negative slope. Finite ends need no such condition.
find_initial_points <- function(logh, domain) {
  lo <- domain[1]; hi <- domain[2]
  if (is.finite(lo) && is.finite(hi)) {
    xs <- c(lo, lo + 0.25 * (hi - lo), lo + 0.5 * (hi - lo),
            lo + 0.75 * (hi - lo), hi)
  } else if (is.finite(lo)) {
    xs <- c(lo, lo + 1, lo + 2, lo + 4)
  } else if (is.finite(hi)) {
    xs <- c(hi - 4, hi - 2, hi - 1, hi)
  } else {
    xs <- c(-2, -1, 0, 1, 2)
  }
  xs <- sort(unique(xs))
  for (it in 1:60) {
    hps <- h_prime(xs, logh)
    need_pos <- (!is.finite(lo)) && !any(hps > 0)
    need_neg <- (!is.finite(hi)) && !any(hps < 0)
    if (!need_pos && !need_neg) break
    if (is.finite(lo) && is.finite(hi)) {
      mids <- (xs[-1L] + xs[-length(xs)]) / 2
      xs <- c(xs, mids)
    } else {
      span <- max(abs(xs)) + 2
      xs <- c(xs, -span, span)
    }
    xs <- sort(unique(xs[xs >= lo & xs <= hi]))
    if (length(xs) > 200L) break
  }
  if (is.finite(lo)) xs <- c(lo, xs)
  if (is.finite(hi)) xs <- c(xs, hi)
  xs <- sort(unique(xs))
  if (length(xs) < 2L)
    stop("Could not find at least two valid initial points.", call. = FALSE)
  list(xs = xs, hps = h_prime(xs, logh), hs = logh(xs))
}
'''
